import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const node = new THREE.Group();
  node.position.set(0, 0, 0);

  // Dimensions
  const ribbonW = 7.0;
  const ribbonH = 0.35;
  const tickW = 0.02;
  const tickH = 0.14;
  const gapSize = 0.5;
  const floatZ = 0.02;
  const fadeWidth = 0.6;

  // Colors
  const bgColor = 0x0b0b10;
  const surfaceColor = 0x111117;
  const paperColor = 0xe8ecf2;
  const accentColor = 0xff2a38;
  const hairlineColor = 0x23232b;

  // Base plane
  const baseGeo = new THREE.PlaneGeometry(ribbonW, ribbonH);
  const baseMat = new THREE.MeshStandardNodeMaterial({
    color: surfaceColor,
    metalness: 0.2,
    roughness: 0.6,
    side: THREE.DoubleSide
  });
  const basePlane = new THREE.Mesh(baseGeo, baseMat);
  node.add(basePlane);

  // Hairlines (top and bottom)
  const hairGeo = new THREE.PlaneGeometry(ribbonW, 0.006);
  const hairMat = new THREE.MeshStandardNodeMaterial({
    color: hairlineColor,
    metalness: 0.2,
    roughness: 0.6,
    side: THREE.DoubleSide
  });

  const topHair = new THREE.Mesh(hairGeo, hairMat);
  topHair.position.y = ribbonH / 2 - 0.003;
  topHair.position.z = 0.001;
  node.add(topHair);

  const botHair = new THREE.Mesh(hairGeo, hairMat);
  botHair.position.y = -ribbonH / 2 + 0.003;
  botHair.position.z = 0.001;
  node.add(botHair);

  // Scrolling content container
  const container = new THREE.Group();
  node.add(container);

  // Ticker entries
  const entries = config.textContent || [
    "CAL NA-01 BEAT 28800 VPH",
    "POWER RESERVE 72H",
    "CASE 40.5 MM 904L",
    "REF 5811 IN STOCK",
    "WAITLIST 1204",
    "NEXT FITTING JUL 18"
  ];

  let stripW = 0;

  // Build entries with separators
  entries.forEach((text) => {
    // Create text mesh
    const textMesh = ctx.fontAtlas.createTextMesh(text, {
      fontSize: 0.13,
      fontWeight: 700,
      color: paperColor,
      align: 'left'
    });

    textMesh.geometry.computeBoundingBox();
    const tW = textMesh.geometry.boundingBox.max.x - textMesh.geometry.boundingBox.min.x;

    textMesh.position.set(stripW, 0, floatZ);
    container.add(textMesh);

    stripW += tW + gapSize;

    // Create separator tick
    const tGeo = new THREE.PlaneGeometry(tickW, tickH);
    const tMat = new THREE.MeshStandardNodeMaterial({
      color: accentColor,
      emissive: accentColor,
      emissiveIntensity: 1.5,
      metalness: 0.2,
      roughness: 0.6,
      side: THREE.DoubleSide
    });
    const tick = new THREE.Mesh(tGeo, tMat);
    tick.position.set(stripW + tickW / 2, 0, 0.001);
    container.add(tick);

    stripW += tickW + gapSize;
  });

  // Clone container for seamless loop
  const cloned = container.clone(true);
  cloned.position.x = stripW;
  container.add(cloned);

  // Animation (0.4 units/sec leftward)
  const loopDist = stripW * 2;
  const duration = loopDist / 0.4;

  const tl = gsap.timeline({ repeat: -1 });
  tl.to(container.position, {
    x: -loopDist,
    duration,
    ease: 'none'
  });

  // Create edge fade texture (DataTexture to avoid DOM)
  const texW = 256;
  const data = new Uint8Array(texW * 4);

  for (let i = 0; i < texW; i++) {
    const norm = i / texW;
    let alpha = 0;

    if (norm < 0.09) {
      // Left fade: opaque → transparent
      alpha = Math.round((1 - norm / 0.09) * 255);
    } else if (norm > 0.91) {
      // Right fade: transparent → opaque
      alpha = Math.round(((norm - 0.91) / 0.09) * 255);
    }

    data[i * 4 + 0] = 11;
    data[i * 4 + 1] = 11;
    data[i * 4 + 2] = 16;
    data[i * 4 + 3] = alpha;
  }

  const fadeTex = new THREE.DataTexture(data, texW, 1, THREE.RGBAFormat);
  fadeTex.needsUpdate = true;
  fadeTex.magFilter = THREE.LinearFilter;
  fadeTex.minFilter = THREE.LinearFilter;

  // Edge fade planes
  const fGeo = new THREE.PlaneGeometry(fadeWidth, ribbonH + 0.2);

  const lMat = new THREE.MeshBasicNodeMaterial({
    map: fadeTex,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide
  });
  const left = new THREE.Mesh(fGeo, lMat);
  left.position.set(-ribbonW / 2 + fadeWidth / 2, 0, 0.005);
  node.add(left);

  const rMat = new THREE.MeshBasicNodeMaterial({
    map: fadeTex,
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide
  });
  const right = new THREE.Mesh(fGeo, rMat);
  right.position.set(ribbonW / 2 - fadeWidth / 2, 0, 0.005);
  right.scale.x = -1; // Mirror fade
  node.add(right);

  // Apply fly-through primitive
  if (ctx.primitives?.['fly-through']) {
    ctx.primitives['fly-through'](node, { depthUnits: 0, speed: 0.4 });
  }

  // Cleanup
  node.userData.cleanup = () => {
    tl.kill();
    baseMat.dispose();
    hairMat.dispose();
    lMat.dispose();
    rMat.dispose();
    baseGeo.dispose();
    hairGeo.dispose();
    fGeo.dispose();
    fadeTex.dispose();
    container.traverse(c => {
      if (c.geometry) c.geometry.dispose();
      if (c.material) c.material.dispose();
    });
  };

  node.userData.handlers = {};

  return node;
}
